/**
 * Table with sorting, selection, pagination, loading and empty states (`design/components/data-table.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/data-table.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { createUniqueId, mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Each,
  ResolvedSlot,
  agentMember,
  claimSlot,
  createCell,
  createDerived,
  createKept,
  elementRef,
  itemOf,
  resolveSlot,
  scope,
  type Defaults,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/data-table.module.css'
import Button from '../controls/Button'
import Checkbox from '../controls/Checkbox'
import EmptyState, { type EmptyStateProps } from './EmptyState'
import Inline from '../layout/Inline'
import Skeleton from './Skeleton'
import Table, { type SortDirection } from './Table'
import TableBody from './TableBody'
import TableCell from './TableCell'
import TableHead from './TableHead'
import TableHeader from './TableHeader'
import TableRow from './TableRow'

export interface DataTableColumn<Row> {
  key: string
  header: string
  /** Defaults to `String(row[key])`, the common case. */
  cell?: (row: Row) => JSX.Element | string
  sortable?: boolean
  numeric?: boolean
}

export interface DataTableSort {
  key: string
  direction: SortDirection
}

export interface DataTableRowDetail<Row> {
  row: Row
  /**
   * Closes this row's detail. When focus is inside the detail it moves to the row's
   * disclosure first, because a focused element that leaves the page leaves focus on
   * the page itself. It does nothing for a row that is not open.
   */
  close: () => void
}

export interface DataTableMessages {
  /** The bulk bar's count. */
  selected: (count: number) => string
  selectAll: string
  /** The row checkbox's name when `getRowLabel` is not supplied. */
  selectRow: string
  /**
   * Names a row's disclosure, from what `getRowName` returns for the row, and names
   * the expansion column's header, called with `undefined`. Optional, so messages
   * written for a table without `rowDetail` still type-check.
   */
  detailsLabel?: (rowName: string | undefined) => string
}

export interface DataTableProps<Row> {
  /**
   * Shown only while something is selected.
   */
  bulkActions?: JSX.Element
  columns: DataTableColumn<Row>[]
  data: Row[]
  /**
   * The rows open at first, while the table holds the set. The set keeps the id of a row that
   * leaves `data`, so a row that comes back with its page is still open.
   */
  defaultExpanded?: ReadonlySet<string>
  /**
   * Required, because a list without a designed empty state has a bug.
   */
  emptyState: EmptyStateProps
  /**
   * The open rows by id. Controlled when given; without it the table holds the set.
   */
  expanded?: ReadonlySet<string>
  getRowId: (row: Row) => string
  /**
   * The whole name of a row's checkbox ("Select Invoice 12"), so a screen reader does not hear
   * "Select row" on every row. Only the checkbox reads it.
   */
  getRowLabel?: (row: Row) => string
  /**
   * The row's own name ("Invoice 12"). `messages.detailsLabel` names the row's disclosure from
   * it ("Details for Invoice 12"). It is not `getRowLabel`, which is a whole control's name: a
   * disclosure named from it would read "Details for Select Invoice 12".
   */
  getRowName?: (row: Row) => string
  /**
   * Whether a row has a detail. A row it refuses has an empty cell in the expansion column and
   * never draws a detail row, whatever `expanded` holds. A function that draws cannot report
   * that it drew nothing, so the table asks this before it draws the disclosure. Without it
   * every row has one.
   */
  isRowExpandable?: (row: Row) => boolean
  label: string
  loading?: boolean
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: DataTableMessages
  /**
   * Called with the next set of open rows, controlled or not.
   */
  onExpandedChange?: (next: ReadonlySet<string>) => void
  /**
   * Opens the row. Per the "row `interactive` handlers" rule in `data-table.md`, a click on the
   * checkbox selects and does *not* open.
   */
  onRowClick?: (row: Row) => void
  onSelectionChange?: (next: ReadonlySet<string>) => void
  onSortChange?: (sort: DataTableSort) => void
  /**
   * A `Pagination` or a `CursorPagination`, rendered below the table.
   */
  pagination?: JSX.Element
  /**
   * Passing it turns expansion on: each row gets a disclosure, and an open row draws what this
   * returns in a full-width row under itself. It takes one object, so every renderer hands the
   * same named values, `row` and `close`. A detail closes itself with `close`: a caller that
   * only removes the id from `expanded` while focus is inside the detail leaves focus on the
   * page.
   */
  rowDetail?: (arg: DataTableRowDetail<Row>) => JSX.Element
  /**
   * Passing it turns selection on, even as an empty set.
   */
  selection?: ReadonlySet<string>
  /**
   * Controlled; the type allows exactly one sorted column.
   */
  sort?: DataTableSort
  stickyHeader?: boolean
}

/** Table with sorting, selection, pagination, loading and empty states. */
export default function DataTable<Row>(given: DataTableProps<Row>): JSX.Element {
  const props = mergeProps(
    {
      loading: false,
      messages: (() => ({
        selected: (count: number) => `${count} selected`,
        selectAll: 'Select all',
        selectRow: 'Select row',
      }))(),
    } as Defaults<DataTableProps<Row>, 'loading' | 'messages'>,
    claimSlot(given),
  )
  return scope(() => {
    const emptyStateKept = createKept(() => props.emptyState)
    const uid = createUniqueId()
    const root = elementRef<HTMLElement>()
    const paginationSlot = resolveSlot(() => props.pagination)
    const ownExpanded = createCell(props.defaultExpanded ?? new Set<string>())
    const selectable = createDerived(() => props.selection !== undefined)
    const expandable = createDerived(() => props.rowDetail !== undefined)
    const open = createDerived(() => props.expanded ?? ownExpanded.value)
    const canExpand = createDerived(
      () =>
        (row: Row): boolean =>
          props.isRowExpandable?.(row) ?? true,
    )
    const detailsLabel = createDerived(
      () =>
        props.messages.detailsLabel ??
        ((rowName: string | undefined): string =>
          rowName === undefined ? 'Details' : `Details for ${rowName}`),
    )
    const span = createDerived(() => props.columns.length + (selectable.value ? 1 : 0) + 1)
    const ids = createDerived(() => props.data.map((row) => props.getRowId(row)))
    const selectedCount = createDerived(() => props.selection?.size ?? 0)
    const selectedHere = createDerived(
      () => ids.value.filter((id) => props.selection?.has(id)).length,
    )
    const allSelected = createDerived(
      () => selectable.value && ids.value.length > 0 && selectedHere.value === ids.value.length,
    )
    const someSelected = createDerived(() => selectedHere.value > 0 && !allSelected.value)
    const headerChecked = createDerived(() =>
      allSelected.value ? true : someSelected.value ? 'indeterminate' : false,
    )
    const bar = createDerived(() => selectable.value && selectedCount.value > 0)
    const empty = createDerived(() => !props.loading && props.data.length === 0)
    const skeletons = createDerived(() => Array.from({ length: 5 }, (_, index) => index))
    const cellOf = createDerived(
      () =>
        (column: DataTableColumn<Row>, row: Row): JSX.Element | string => {
          if (column.cell !== undefined) return column.cell(row)
          const value = (row as Record<string, unknown>)[column.key]
          return value === undefined || value === null ? '' : String(value)
        },
    )
    const sortTo = createDerived(() => (column: DataTableColumn<Row>): DataTableSort => ({
      key: column.key,
      direction: props.sort?.key === column.key && props.sort?.direction === 'asc' ? 'desc' : 'asc',
    }))
    const toggleAll = createDerived(() => () => {
      if (props.selection === undefined) return
      const next = new Set(props.selection)
      for (const id of ids.value) {
        if (allSelected.value) next.delete(id)
        else next.add(id)
      }
      props.onSelectionChange?.(next)
    })
    const toggleRow = createDerived(() => (id: string) => {
      if (props.selection === undefined) return
      const next = new Set(props.selection)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      props.onSelectionChange?.(next)
    })
    const toggleExpanded = createDerived(() => (id: string) => {
      const next = new Set(open.value)
      if (next.has(id)) next.delete(id)
      else next.add(id)
      ownExpanded.value = next
      props.onExpandedChange?.(next)
    })
    const closeDetail = createDerived(() => (id: string) => {
      if (!open.value.has(id)) return
      const element = root.value as HTMLElement | null
      const detailId = CSS.escape(`${uid}-detail-${ids.value.indexOf(id)}`)
      if (element?.querySelector(`#${detailId}`)?.matches(':focus-within') === true)
        element.querySelector<HTMLElement>(`[aria-controls="${detailId}"]`)?.focus()
      const next = new Set(open.value)
      next.delete(id)
      ownExpanded.value = next
      props.onExpandedChange?.(next)
    })
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'DataTable',
        element: () => root.value,
        state: () => ({
          'sort-key': props.sort?.key ?? null,
          'sort-direction': props.sort?.direction ?? '',
          columns: props.columns.map((column) => ({
            id: column.key,
            label: column.header,
            ...(column.sortable === true ? {} : { disabled: true }),
          })),
          selection: [...(props.selection ?? [])],
          expanded: [...open.value],
          loading: props.loading,
        }),
        actions: {
          'sort-ascending': {
            argument: 'id',
            run: (value) =>
              (props.sort?.key === value && props.sort?.direction === 'asc') ||
              props.onSortChange?.({ key: value, direction: 'asc' }),
          },
          'sort-descending': {
            argument: 'id',
            run: (value) =>
              (props.sort?.key === value && props.sort?.direction === 'desc') ||
              props.onSortChange?.({ key: value, direction: 'desc' }),
          },
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <div
        class={styles.table}
        data-loading={props.loading ? '' : undefined}
        data-empty={empty.value ? '' : undefined}
        aria-busy={props.loading ? true : undefined}
        data-member="data-table"
        ref={root.attach}
      >
        {bar.value ? (
          <ResolvedSlot of={() => props.bulkActions}>
            {(bulkActionsSlot) => (
              <div class={styles.bulkBar}>
                <Inline gap={4} align="center" justify="between" wrap={true}>
                  {/* count */}
                  <span class={styles.bulkCount} aria-live="polite">
                    {props.messages.selected(selectedCount.value)}
                  </span>
                  {bulkActionsSlot.filled() ? (
                    <Inline gap={3} align="center" wrap={true}>
                      {bulkActionsSlot()}
                    </Inline>
                  ) : null}
                </Inline>
              </div>
            )}
          </ResolvedSlot>
        ) : null}
        {empty.value ? (
          <EmptyState
            icon={emptyStateKept.value.icon}
            title={emptyStateKept.value.title}
            description={emptyStateKept.value.description}
            action={
              emptyStateKept.value.action !== undefined ? emptyStateKept.value.action : undefined
            }
            secondaryAction={
              emptyStateKept.value.secondaryAction !== undefined
                ? emptyStateKept.value.secondaryAction
                : undefined
            }
          />
        ) : (
          <Table
            label={props.label}
            caption={props.label}
            stickyHeader={props.stickyHeader}
            grid={true}
            multiselectable={selectable.value}
          >
            <TableHead>
              <TableRow>
                {selectable.value ? (
                  <TableHeader>
                    <Checkbox
                      aria-label={props.messages.selectAll}
                      checked={headerChecked.value}
                      disabled={props.loading || ids.value.length === 0}
                      onCheckedChange={() => toggleAll.value()}
                    />
                  </TableHeader>
                ) : null}
                {expandable.value ? (
                  <TableHeader>
                    <span class={styles.expandLabel} data-undrawn={''}>
                      {detailsLabel.value(undefined)}
                    </span>
                  </TableHeader>
                ) : null}
                <Each of={props.columns} by={(column) => column.key} renew>
                  {(column) => (
                    <TableHeader
                      numeric={column.numeric}
                      sortable={column.sortable}
                      sortDirection={
                        props.sort?.key === column.key ? props.sort?.direction : undefined
                      }
                      onSort={() =>
                        column.sortable && props.onSortChange?.(sortTo.value(itemOf(column)))
                      }
                    >
                      {column.header}
                    </TableHeader>
                  )}
                </Each>
              </TableRow>
            </TableHead>
            <TableBody>
              {props.loading ? (
                <Each of={skeletons.value} by={(index) => `skeleton-${index}`}>
                  {() => (
                    <TableRow>
                      {selectable.value ? (
                        <TableCell>
                          <Skeleton shape="circle" size={4} />
                        </TableCell>
                      ) : null}
                      {expandable.value ? (
                        <TableCell>
                          <Skeleton shape="circle" size={4} />
                        </TableCell>
                      ) : null}
                      <Each of={props.columns} by={(column) => column.key} renew>
                        {(column) => (
                          <TableCell numeric={column.numeric}>
                            <Skeleton textStep="sm" />
                          </TableCell>
                        )}
                      </Each>
                    </TableRow>
                  )}
                </Each>
              ) : (
                <Each of={props.data} by={(row) => props.getRowId(row)} renew>
                  {(row, index) => (
                    <>
                      <TableRow
                        selected={props.selection?.has(props.getRowId(itemOf(row)))}
                        interactive={props.onRowClick !== undefined}
                        onClick={() =>
                          props.onRowClick !== undefined && props.onRowClick?.(itemOf(row))
                        }
                      >
                        {selectable.value ? (
                          <TableCell>
                            <span
                              class={styles.selectCell}
                              onclick={($event: MouseEvent) => $event.stopPropagation()}
                            >
                              <Checkbox
                                aria-label={
                                  props.getRowLabel?.(itemOf(row)) ?? props.messages.selectRow
                                }
                                checked={props.selection?.has(props.getRowId(itemOf(row))) ?? false}
                                onCheckedChange={() => toggleRow.value(props.getRowId(itemOf(row)))}
                              />
                            </span>
                          </TableCell>
                        ) : null}
                        {expandable.value ? (
                          <TableCell>
                            {canExpand.value(itemOf(row)) ? (
                              <span
                                class={styles.expandCell}
                                onclick={($event: MouseEvent) => $event.stopPropagation()}
                              >
                                <Button
                                  variant="ghost"
                                  tone="neutral"
                                  size="sm"
                                  iconOnly={true}
                                  icon={
                                    canExpand.value(itemOf(row)) &&
                                    open.value.has(props.getRowId(itemOf(row)))
                                      ? 'up'
                                      : 'down'
                                  }
                                  label={detailsLabel.value(props.getRowName?.(itemOf(row)))}
                                  expanded={
                                    canExpand.value(itemOf(row)) &&
                                    open.value.has(props.getRowId(itemOf(row)))
                                  }
                                  aria-controls={
                                    canExpand.value(itemOf(row)) &&
                                    open.value.has(props.getRowId(itemOf(row)))
                                      ? `${uid}-detail-${index()}`
                                      : undefined
                                  }
                                  onClick={() => toggleExpanded.value(props.getRowId(itemOf(row)))}
                                />
                              </span>
                            ) : null}
                          </TableCell>
                        ) : null}
                        <Each of={props.columns} by={(column) => column.key} renew>
                          {(column) => (
                            <TableCell numeric={column.numeric}>
                              {cellOf.value(itemOf(column), itemOf(row))}
                            </TableCell>
                          )}
                        </Each>
                      </TableRow>
                      {expandable.value &&
                      canExpand.value(itemOf(row)) &&
                      open.value.has(props.getRowId(itemOf(row))) ? (
                        <tr id={`${uid}-detail-${index()}`} data-detail={''}>
                          <td class={styles.detailCell} colspan={span.value}>
                            <div class={styles.detail}>
                              {props.rowDetail?.({
                                row: itemOf(row),
                                close: () => closeDetail.value(props.getRowId(itemOf(row))),
                              })}
                            </div>
                          </td>
                        </tr>
                      ) : null}
                    </>
                  )}
                </Each>
              )}
            </TableBody>
          </Table>
        )}
        {paginationSlot.filled() ? (
          <div class={styles.pagination}>
            <Inline gap={3} justify="end" wrap={true}>
              {paginationSlot()}
            </Inline>
          </div>
        ) : null}
      </div>
    )
  })
}
